def clean(df):
    df = df.copy()

    # Normalize text labels
    for col in ['species', 'island', 'sex']:
        if col in df.columns:
            df[col] = df[col].astype('string').str.strip()

    if 'sex' in df.columns:
        df['sex'] = df['sex'].str.lower()
        df.loc[~df['sex'].isin(['male', 'female']), 'sex'] = pd.NA

    # Ensure numeric columns are numeric
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    # Fix flipper length sign errors and enforce valid range
    if 'flipper_length_mm' in df.columns:
        s = df['flipper_length_mm']
        df.loc[s < 0, 'flipper_length_mm'] = s[s < 0].abs()
        df.loc[~df['flipper_length_mm'].between(170, 235), 'flipper_length_mm'] = pd.NA

    # Fix body mass unit/out-of-range values
    if 'body_mass_g' in df.columns:
        s = df['body_mass_g']
        df.loc[s > 6500, 'body_mass_g'] = s[s > 6500] / 1000
        df.loc[~df['body_mass_g'].between(2500, 6500), 'body_mass_g'] = pd.NA

    # Enforce bill length range
    if 'bill_length_mm' in df.columns:
        df.loc[~df['bill_length_mm'].between(30, 60), 'bill_length_mm'] = pd.NA

    return df


def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'flipper_length_mm'])
    result = d.groupby('species', dropna=True)['flipper_length_mm'].mean()
    return {str(k): float(v) for k, v in result.items()}
